from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry triplet_margin_kernel(
    .param .u64 anchor_ptr,
    .param .u64 pos_ptr,
    .param .u64 neg_ptr,
    .param .u64 out_ptr,
    .param .u64 block_sums_ptr,
    .param .u64 counter_ptr,
    .param .u32 batch_size,
    .param .u32 dim_size,
    .param .f32 margin,
    .param .f32 eps
)
{
    .reg .pred  %p<8>;
    .reg .b32   %r<32>;
    .reg .b64   %rd<32>;
    .reg .f32   %f<32>;

    .shared .align 4 .b8 shmem[4096];

    // Load parameters
    ld.param.u64 %rd1, [anchor_ptr];
    ld.param.u64 %rd2, [pos_ptr];
    ld.param.u64 %rd3, [neg_ptr];
    ld.param.u64 %rd4, [out_ptr];
    ld.param.u64 %rd5, [block_sums_ptr];
    ld.param.u64 %rd6, [counter_ptr];
    ld.param.u32 %r20, [batch_size];
    ld.param.u32 %r21, [dim_size];
    ld.param.f32 %f20, [margin];
    ld.param.f32 %f21, [eps];

    // Thread/block info
    mov.u32 %r0, %tid.x;
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %nctaid.x;

    // gtid = blockIdx.x * blockDim.x + threadIdx.x
    mad.lo.s32 %r4, %r1, %r2, %r0;
    // stride = blockDim.x * gridDim.x
    mul.lo.u32 %r5, %r2, %r3;

    // Local accumulator
    mov.f32 %f0, 0f00000000;

    // i loop over batch with stride
LOOP_I:
    setp.ge.u32 %p0, %r4, %r20;
    @%p0 bra LOOP_I_END;

    // base offset in elements = i * dim_size
    mul.wide.u32 %rd10, %r4, %r21;      // 64-bit product
    shl.b64 %rd11, %rd10, 2;            // bytes offset ( *4 )

    add.s64 %rd12, %rd1, %rd11;         // ptrA
    add.s64 %rd13, %rd2, %rd11;         // ptrP
    add.s64 %rd14, %rd3, %rd11;         // ptrN

    mov.f32 %f1, 0f00000000;            // sumAP
    mov.f32 %f2, 0f00000000;            // sumAN
    mov.u32 %r6, 0;                     // j = 0 (vector iters)
    // Vectorized loop setup: vec_iters = dim_size >> 2, rem = dim_size & 3
    shr.u32 %r22, %r21, 2;
    and.b32 %r23, %r21, 3;
LOOP_JV:
    setp.ge.u32 %p1, %r6, %r22;
    @%p1 bra LOOP_JV_END;
    ld.global.v4.f32 {%f3,%f4,%f5,%f6}, [%rd12];         // a[0..3]
    ld.global.v4.f32 {%f7,%f8,%f9,%f10}, [%rd13];        // p[0..3]
    ld.global.v4.f32 {%f11,%f12,%f13,%f14}, [%rd14];     // n[0..3]
    sub.f32 %f16, %f3, %f7;
    fma.rn.f32 %f1, %f16, %f16, %f1;
    sub.f32 %f17, %f3, %f11;
    fma.rn.f32 %f2, %f17, %f17, %f2;
    sub.f32 %f16, %f4, %f8;
    fma.rn.f32 %f1, %f16, %f16, %f1;
    sub.f32 %f17, %f4, %f12;
    fma.rn.f32 %f2, %f17, %f17, %f2;
    sub.f32 %f16, %f5, %f9;
    fma.rn.f32 %f1, %f16, %f16, %f1;
    sub.f32 %f17, %f5, %f13;
    fma.rn.f32 %f2, %f17, %f17, %f2;
    sub.f32 %f16, %f6, %f10;
    fma.rn.f32 %f1, %f16, %f16, %f1;
    sub.f32 %f17, %f6, %f14;
    fma.rn.f32 %f2, %f17, %f17, %f2;
    add.u32 %r6, %r6, 1;
    add.s64 %rd12, %rd12, 16;
    add.s64 %rd13, %rd13, 16;
    add.s64 %rd14, %rd14, 16;
    bra LOOP_JV;
LOOP_JV_END:
    // Tail loop for remaining elements (0..3)
    mov.u32 %r12, 0;
LOOP_JT:
    setp.ge.u32 %p1, %r12, %r23;
    @%p1 bra LOOP_JT_END;
    ld.global.f32 %f3, [%rd12];         // a
    ld.global.f32 %f4, [%rd13];         // p
    ld.global.f32 %f5, [%rd14];         // n
    sub.f32 %f6, %f3, %f4;              // a - p
    fma.rn.f32 %f1, %f6, %f6, %f1;      // sumAP += (a-p)^2
    sub.f32 %f7, %f3, %f5;              // a - n
    fma.rn.f32 %f2, %f7, %f7, %f2;      // sumAN += (a-n)^2
    add.u32 %r12, %r12, 1;
    add.s64 %rd12, %rd12, 4;
    add.s64 %rd13, %rd13, 4;
    add.s64 %rd14, %rd14, 4;
    bra LOOP_JT;
LOOP_JT_END:
LOOP_J_END:
    add.f32 %f8, %f1, %f21;             // sumAP + eps
    add.f32 %f9, %f2, %f21;             // sumAN + eps
    sqrt.rn.f32 %f10, %f8;              // d_ap
    sqrt.rn.f32 %f11, %f9;              // d_an
    sub.f32 %f12, %f10, %f11;           // d_ap - d_an
    add.f32 %f13, %f12, %f20;           // + margin
    max.f32 %f13, %f13, 0f00000000;     // relu
    add.f32 %f0, %f0, %f13;             // local_sum += loss_i

    add.u32 %r4, %r4, %r5;
    bra LOOP_I;

LOOP_I_END:

    // Write to shared memory for block reduction
    mov.u64 %rd20, shmem;
    mul.wide.u32 %rd21, %r0, 4;
    add.s64 %rd22, %rd20, %rd21;
    st.shared.f32 [%rd22], %f0;
    bar.sync 0;

    // Reduction in shared memory
    mov.u32 %r7, %r2;        // s = blockDim
    shr.u32 %r7, %r7, 1;     // s >>= 1

RED_LOOP:
    setp.eq.u32 %p2, %r7, 0;
    @%p2 bra RED_END;

    setp.lt.u32 %p3, %r0, %r7;
    @!%p3 bra RED_SKIP;

    // partner index = tid + s
    add.u32 %r8, %r0, %r7;
    mul.wide.u32 %rd23, %r8, 4;
    add.s64 %rd24, %rd20, %rd23;
    ld.shared.f32 %f14, [%rd24];

    // own
    mul.wide.u32 %rd25, %r0, 4;
    add.s64 %rd26, %rd20, %rd25;
    ld.shared.f32 %f15, [%rd26];
    add.f32 %f16, %f15, %f14;
    st.shared.f32 [%rd26], %f16;

RED_SKIP:
    bar.sync 0;
    shr.u32 %r7, %r7, 1;
    bra RED_LOOP;

RED_END:
    // Thread 0 writes block sum and participates in global reduction
    setp.ne.u32 %p4, %r0, 0;
    @%p4 bra K_EXIT;

    // block sum at shmem[0]
    ld.shared.f32 %f17, [shmem];

    // store to block_sums[blockIdx.x]
    mul.wide.u32 %rd27, %r1, 4;
    add.s64 %rd28, %rd5, %rd27;
    st.global.f32 [%rd28], %f17;

    // ensure visibility before incrementing counter
    membar.gl;

    // atomic increment: old = atomicAdd(counter, 1)
    atom.global.add.u32 %r9, [%rd6], 1;

    // if old == gridDim - 1, this is the last block
    sub.u32 %r10, %r3, 1;
    setp.eq.u32 %p5, %r9, %r10;
    @!%p5 bra K_EXIT;

    // Last block does final sum and write mean
    mov.f32 %f18, 0f00000000;
    mov.u32 %r11, 0;

FINAL_SUM_LOOP:
    setp.ge.u32 %p6, %r11, %r3;
    @%p6 bra FINAL_SUM_END;

    mul.wide.u32 %rd29, %r11, 4;
    add.s64 %rd30, %rd5, %rd29;
    ld.global.f32 %f19, [%rd30];
    add.f32 %f18, %f18, %f19;

    add.u32 %r11, %r11, 1;
    bra FINAL_SUM_LOOP;

FINAL_SUM_END:
    cvt.rn.f32.s32 %f22, %r20;
    div.rn.f32 %f23, %f18, %f22;
    st.global.f32 [%rd4], %f23;

K_EXIT:
    ret;
}
