                positive.contiguous(),
                negative.contiguous(),
                out,
                block_sums,
                counter,
                i32(batch_size),
                i32(dim_size),
                f32(self.margin),
                f32(1.0e-6),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(anchor.device),
        )
